from fastapi import FastAPI, Path, Query
from pydantic import BaseModel, Field

app = FastAPI(title='E-Commerce API', version='1.0.0')

class ItemResponse(BaseModel):
  id: int
  name: str = Field(description='The name of the item', example='Wireless Mouse')
  price: float = Field(gt=0, description='Price in USD')

# ✅ NEW: Generates complete OpenAPI 3.1 schema and interactive /docs automatically!
@app.get('/items/{id}', response_model=ItemResponse, tags=['Items'], summary='Fetch Item by ID')
def get_item(id: int = Path(..., gt=0, description='Item Database ID')):
  return {'id': id, 'name': 'Wireless Mouse', 'price': 29.99}
